// Regenerates test/fixtures/blobs.ts, the binary fixtures the chat.db tests insert: plists made by plutil, and
// attributedBody typedstreams made by Foundation's own NSArchiver (through swift), the formats Messages writes.
// macOS only. The tests read the committed output, so running them needs neither tool.
// Usage: npx tsx test/fixtures/generate-blobs.ts
import { execFileSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const OUT = new URL('./blobs.ts', import.meta.url);

/** NSAttributedString -> NSArchiver typedstream, one hex line per text. A mention marks the first word. */
function attributedBodies(items: { text: string; mention?: string }[]): string[] {
  const dir = mkdtempSync(join(tmpdir(), 'imsg-blobs-'));
  try {
    const src = join(dir, 'archive.swift');
    writeFileSync(
      src,
      `import Foundation
let items = try! JSONSerialization.jsonObject(with: CommandLine.arguments[1].data(using: .utf8)!) as! [[String: String]]
for item in items {
  let s = NSMutableAttributedString(string: item["text"]!)
  let all = NSRange(location: 0, length: s.length)
  s.addAttribute(NSAttributedString.Key("__kIMMessagePartAttributeName"), value: 0, range: all)
  if let handle = item["mention"] {
    let word = (item["text"]! as NSString).range(of: " ").location
    s.addAttribute(NSAttributedString.Key("__kIMMentionConfirmedMention"), value: handle, range: NSRange(location: 0, length: word))
  }
  print(NSArchiver.archivedData(withRootObject: s).map { String(format: "%02x", $0) }.joined())
}
`,
    );
    const out = execFileSync('xcrun', ['swift', '-suppress-warnings', src, JSON.stringify(items)], {
      encoding: 'utf8',
    });
    return out.trim().split('\n');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

/** XML plist body -> base64 binary plist, via plutil. */
const plist = (xml: string) =>
  execFileSync('plutil', ['-convert', 'binary1', '-o', '-', '-'], {
    input: `<?xml version="1.0" encoding="UTF-8"?><plist version="1.0">${xml}</plist>`,
  }).toString('base64');

const uid = (n: number) => `<dict><key>CF$UID</key><integer>${n}</integer></dict>`;
/** message_summary_info for an edited message: each version's attributedBody and its time. */
const editHistory = (versions: string[]) =>
  `<dict><key>ec</key><dict><key>0</key><array>${versions
    .map(
      (hex, i) =>
        `<dict><key>t</key><data>${Buffer.from(hex, 'hex').toString('base64')}</data><key>d</key><real>${100 + 60 * i}</real></dict>`,
    )
    .join('')}</array></dict></dict>`;
/** payload_data of a rich link: an NSKeyedArchiver graph with the title and URL. */
const richLink = (title: string, url: string) =>
  `<dict><key>$archiver</key><string>NSKeyedArchiver</string><key>$version</key><integer>100000</integer><key>$top</key><dict><key>root</key>${uid(1)}</dict><key>$objects</key><array><string>$null</string><dict><key>richLinkMetadata</key>${uid(2)}</dict><dict><key>title</key>${uid(3)}<key>URL</key>${uid(4)}</dict><string>${title}</string><dict><key>NS.relative</key>${uid(5)}</dict><string>${url}</string></array></dict>`;

const BODY_TEXTS = {
  ascii: { text: 'see you at 8' },
  emoji: { text: 'on my way 🚗💨 café' },
  long: { text: 'The cabin has a wood stove, so bring warm socks. '.repeat(4).trim() },
  mention: { text: 'Jo can you grab ice?', mention: '+15555550133' },
} as const;
const EDITS = ["perfect, I'll bring the girl", "perfect, I'll bring the grill", 'see you at 7', 'see you at 8'];

const names = Object.keys(BODY_TEXTS) as (keyof typeof BODY_TEXTS)[];
const hex = attributedBodies([...names.map((n) => BODY_TEXTS[n]), ...EDITS.map((text) => ({ text }))]);
const bodies = names.map((n, i) => ({ name: n, ...BODY_TEXTS[n], hex: hex[i] }));
const edit = hex.slice(names.length);

const plists: [string, string, string][] = [
  [
    'unsent',
    'message_summary_info of an unsent message',
    plist('<dict><key>rp</key><array><integer>0</integer></array></dict>'),
  ],
  ['editGrill', `edit history: "${EDITS[0]}" then "${EDITS[1]}"`, plist(editHistory([edit[0], edit[1]]))],
  ['edit7to8', `edit history: "${EDITS[2]}" then "${EDITS[3]}"`, plist(editHistory([edit[2], edit[3]]))],
  [
    'linkCabin',
    'rich link "Lakeside cabin" to https://example.com/cabin',
    plist(richLink('Lakeside cabin', 'https://example.com/cabin')),
  ],
  [
    'linkStays',
    'rich link "Lakeside cabin" to https://www.stays.example/rooms/48213',
    plist(richLink('Lakeside cabin', 'https://www.stays.example/rooms/48213')),
  ],
  [
    'protoKey',
    'a dict whose key is "__proto__"',
    plist('<dict><key>__proto__</key><dict><key>polluted</key><true/></dict><key>ok</key><string>yes</string></dict>'),
  ],
];

writeFileSync(
  OUT,
  `// Generated by test/fixtures/generate-blobs.ts; edit that and re-run it instead of editing this file.
// Synthetic content only.

/** Binary plists (base64) as Messages stores them in message_summary_info and payload_data. */
export const PLIST = {
${plists.map(([k, what, b64]) => `  /** ${what} */\n  ${k}: Buffer.from('${b64}', 'base64'),`).join('\n')}
};

/** attributedBody blobs written by Foundation's NSArchiver, with the text each one holds. */
export const ATTRIBUTED_BODY = {
${bodies.map((b) => `  ${b.name}: {\n    text: ${JSON.stringify(b.text)},\n    blob: Buffer.from('${b.hex}', 'hex'),\n  },`).join('\n')}
};
`,
);
console.log(`wrote ${OUT.pathname}`);
